verification_receipts.patch_excerpt:
diff --git a/scripts/test-executor-profiles.js b/scripts/test-executor-profiles.js
index 3178834..8f6e6f6 100644
--- a/scripts/test-executor-profiles.js
+++ b/scripts/test-executor-profiles.js
@@ -185,4 +185,45 @@ for (const forbidden of ['signature', 'private', 'raw_output', 'env', 'command',
 }
 assert.equal(replay.model_status, 'unknown');

+// Regression: an observation that carries telemetry but no usable model must stay
+// unknown on every surface. A verified receipt proves the run happened, never that
+// the requested model ran, so it may not upgrade the model proof to a match.
+const missingModelObservations = [
+  null,
+  undefined,
+  {},
+  { trusted: true },
+  { model: null, trusted: true },
+  { model: '', trusted: true },
+  { trusted: true, duration_ms: 1200, tokens: 4096, cost: { amount: 0, unit: 'usd', source: 'local' } },
+];
+const verifiedReceipt = profiles.verifyForkReceiptWrapper(wrapper, { publicKey, expected: wrapperInput });
+assert.equal(verifiedReceipt.status, 'verified');
+for (const [index, observation] of missingModelObservations.entries()) {
+  const where = `missing-model observation #${index}`;
+  for (const profile of [local, ...profiles.synthesizeLegacyExecutors(['codex'])]) {
+    assert.deepEqual(profiles.evaluateModelProof(profile, observation), {
+      requested_model: profile.model === null ? 'default' : profile.model,
+      observed_model: null,
+      status: 'unknown',
+      reason_code: 'MODEL_OBSERVATION_MISSING',
+    }, where);
+  }
+
+  const state = profiles.missionControlExecutorState({
+    profile: local, observation, wrapper, verification: verifiedReceipt,
+  });
+  assert.equal(state.receipt_status, 'verified', where);
+  assert.equal(state.model_status, 'unknown', where);
+  assert.equal(state.model_reason_code, 'MODEL_OBSERVATION_MISSING', where);
+  assert.equal(state.observed_model, null, where);
+
+  const unknownReplay = profiles.publicExecutorReplay({
+    profile: local, observation, wrapper, verification: verifiedReceipt,
+  });
+  assert.equal(unknownReplay.model_status, 'unknown', where);
+  assert.equal(unknownReplay.observed_model, null, where);
+  assert(!JSON.stringify(unknownReplay).includes('MATCHED'), `${where} replay claimed a model match`);
+}
+
 process.stdout.write('Executor profiles passed: strict profiles, canonical digests, literal invocations, bound receipts, and honest model proof.\n');
